// Verifies a LendLoop webhook: shared token, timestamp window, HMAC-SHA256
// signature over `${timestamp}.${rawBody}`, and duplicate deliveries.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const token = $env.LENDLOOP_WEBHOOK_TOKEN;
// Auth failures all look the same to the caller, so nothing confirms a guessed token.
const reject = (status, reason) => [{ json: { ok: false, status, reason } }];

if (!secret || !token) return reject(500, 'unavailable');

const safeEqual = (a, b) => {
  const x = Buffer.from(String(a)); const y = Buffer.from(String(b));
  return x.length === y.length && crypto.timingSafeEqual(x, y);
};

if (!safeEqual(headers['x-lendloop-token'] || '', token)) return reject(401, 'unauthorized');

const ts = headers['x-lendloop-timestamp'] || '';
if (!/^\d{10}$/.test(ts)) return reject(401, 'unauthorized');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject(401, 'unauthorized');

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
if (!safeEqual(headers['x-lendloop-signature'] || '', expected)) return reject(401, 'unauthorized');

let payload;
try { payload = JSON.parse(raw); } catch { return reject(400, 'invalid request'); }
if (!payload.idempotencyKey || !payload.event) return reject(400, 'invalid request');

// Already delivered? (keys are recorded only after the email went out)
const seen = ($getWorkflowStaticData('global').seen ||= {});
return [{ json: { ok: true, status: 200, duplicate: !!seen[payload.idempotencyKey], payload } }];

// Turns an event into an email. Uses only the fields the message needs.
const { event, recipient, counterparty, loan } = $json.payload;
const app = $env.LENDLOOP_APP_URL || 'http://localhost:3000';
const dates = loan.startDate === loan.endDate ? loan.startDate : `${loan.startDate} to ${loan.endDate}`;
const who = counterparty.username;
const T = {
  'loan.requested':     [`New request for your ${loan.toolName}`, `${who} would like to borrow your ${loan.toolName} (${dates}). Approve or decline it in LendLoop.`],
  'loan.approved':      [`Your request for ${loan.toolName} was approved`, `${who} approved your request to borrow ${loan.toolName} (${dates}).`],
  'loan.declined':      [`Your request for ${loan.toolName} was declined`, `${who} could not lend you ${loan.toolName} (${dates}).`],
  'loan.cancelled':     [`Request for ${loan.toolName} cancelled`, `${who} cancelled their request to borrow your ${loan.toolName} (${dates}).`],
  'loan.return_pending':[`${who} says ${loan.toolName} is back`, `${who} marked your ${loan.toolName} as returned. Please confirm the return in LendLoop.`],
  'loan.returned':      [`Return of ${loan.toolName} confirmed`, `${who} confirmed they have ${loan.toolName} back. Thanks for using LendLoop!`],
};
const [subject, line] = T[event] || [`LendLoop update: ${event}`, `Something changed on ${loan.toolName}.`];
return [{ json: {
  idempotencyKey: $json.payload.idempotencyKey,
  hasEmail: !!recipient.email,
  to: recipient.email || '',
  subject,
  text: `Hi ${recipient.username},\n\n${line}\n\nOpen LendLoop: ${app}\n`,
} }];

// Record the delivery only now, so a failed send can be retried by Convex.
const key = $('Build email').first().json.idempotencyKey;
const seen = ($getWorkflowStaticData('global').seen ||= {});
const now = Date.now();
seen[key] = now;
for (const k of Object.keys(seen)) if (now - seen[k] > 7 * 24 * 3600 * 1000) delete seen[k];
return [{ json: { ok: true, delivered: key } }];
